SELECT CODE, NAME FROM (SELECT DISTINCT A.SCM_SITE_ID AS CODE, A.SCM_SITE_ID AS NAME, 1 AS ORD FROM SCM_MGR.SCM_MST_SITE A WHERE A.SITE_TYPE = 'SALES' AND A.VALID_YN = 'Y' AND (NVL(TRIM(@divisionId), 'ALL') = 'ALL' OR INSTR(',' || @divisionId || ',', ',' || A.DIVISION_ID || ',') > 0) UNION ALL SELECT COMPANY_ID, COMPANY_ID, 2 FROM SCM_MGR.SCM_MST_COMPANY_SN) ORDER BY ORD, CODE